/** SVG ikon inline: <?= ikon('download') ?> */
function ikon(string $nama, int $ukuran = 18, string $kelas = ''): string
{
    $isi = IKON_LUCIDE[$nama] ?? '';

    return '<svg class="ikon ' . esc($kelas, 'attr') . '" width="' . $ukuran . '" height="' . $ukuran . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' . $isi . '</svg>';
}
